Item.method_code:
    string hindiMarks = this.getProperty("mark_hindi","");
    int Hindi = Int16.Parse(hindiMarks);

	//Changes made in local main branch
	//Changes made in local main branch 2nd time
	//Changes made in local main branch 3rd time


    string englishMarks = this.getProperty("mark_english","");
    int English = int.Parse(englishMarks);

    string historyMarks = this.getProperty("mark_histroy","");
    int History = int.Parse(historyMarks) ;

    string marathiMarks = this.getProperty("mark_marathi","");
    int Marathi = int.Parse(marathiMarks) ;

    string mathMarks = this.getProperty("mark_math","");
    int Math = int.Parse(mathMarks) ;

    string scienceMarks = this.getProperty("mark_science","");
    int Science = int.Parse(scienceMarks) ;

    int total = English+History+Marathi+Math+Science;

    double Calpercentage = ((double)total / 600) * 100;
    string percentage= Calpercentage.ToString();

    String n = this.getProperty("mark_rollno","");


    Item student = this.newItem("Student","get");
    student.setProperty("stud_rollno",n);
    student = student.apply();


    student.setAction("edit");

    student.setProperty("stud_percentage",percentage);

    Item result=student.apply();
    return result;
